    assert_eq!(candidate("Multiple &quot;quotes&quot; and &apos;apostrophes&apos; in this &quot;&apos;string&apos;&quot;"), Multiple "quotes" and 'apostrophes' in this "'string'");
    assert_eq!(candidate("&amp;lt;p&amp;gt;&amp;amp;lt;p&amp;amp;gt;Nested &amp;amp;amp;amp; entities&amp;amp;&lt;/p&amp;amp;gt;&amp;lt;/p&amp;gt;"), &lt;p&gt;&amp;lt;p&amp;gt;Nested &amp;amp;amp; entities&amp;</p&amp;gt;&lt;/p&gt;);
    assert_eq!(candidate("Combining &quot;quotes&quot; and &apos;apostrophes&apos; in &lt;tags&gt;"), Combining "quotes" and 'apostrophes' in <tags>);
    assert_eq!(candidate("&frasl;&frasl;&frasl; should become ///"), /// should become ///);
    assert_eq!(candidate("Combining &amp; &gt; &lt; &quot; &apos; &frasl; in a single string: &amp;gt;&lt;&quot;&apos;&frasl;&amp;lt;&gt;&quot;&apos;&frasl;&amp;"), Combining & > < " ' / in a single string: &gt;<"'/&lt;>"'/&);
    assert_eq!(candidate("&amp;lt; &amp;gt; &amp;amp; &amp;quot; &amp;apos; &amp;frasl;"), &lt; &gt; &amp; &quot; &apos; &frasl;);
    assert_eq!(candidate("&lt;p&gt;This is a &lt;b&gt;bold&lt;/b&gt; paragraph.&lt;/p&gt;"), <p>This is a <b>bold</b> paragraph.</p>);
    assert_eq!(candidate("This is a test: &amp;&amp; &gt;&gt;&gt; &lt;&lt;&lt; &quot;&quot;&quot; &apos;&apos;&apos; &frasl;&frasl;&frasl;"), This is a test: && >>> <<< """ ''' ///);
    assert_eq!(candidate("Nested &lt;div&gt;&lt;p&gt;&amp;nested &lt;span&gt;&amp;&amp; entities&lt;/span&gt;&lt;/p&gt;&lt;/div&gt; &frasl; &lt;em&gt;emphasis&lt;/em&gt;"), Nested <div><p>&nested <span>&& entities</span></p></div> / <em>emphasis</em>);
    assert_eq!(candidate("&amp;lt;a href=&amp;quot;http://example.com&amp;amp;frasl;test&amp;quot;&amp;gt;Link&amp;lt;/a&amp;gt;"), &lt;a href=&quot;http://example.com&amp;frasl;test&quot;&gt;Link&lt;/a&gt;);
    assert_eq!(candidate("&gt;&amp;gt;&amp;gt; Greater than signs &lt;&amp;lt;&amp;lt; and &amp;amp;&gt;&amp;amp;&lt; mixed up &lt;&amp;lt;&amp;lt; &gt;&amp;gt;&amp;gt;"), >&gt;&gt; Greater than signs <&lt;&lt; and &amp;>&amp;< mixed up <&lt;&lt; >&gt;&gt;);
    assert_eq!(candidate("Complex &amp; example: &lt;p&gt;&amp;lt;&amp;gt;&amp;amp;&amp;quot;&amp;apos;&amp;frasl;&lt;/p&gt;"), Complex & example: <p>&lt;&gt;&amp;&quot;&apos;&frasl;</p>);
