    assert_eq!(candidate("Escaping &amp;amp;lt; &amp;amp;gt; &amp;amp;amp; &amp;amp;quot; &amp;amp;apos; &amp;amp;frasl;"), Escaping &amp;lt; &amp;gt; &amp;amp; &amp;quot; &amp;apos; &amp;frasl;);
